INSERT INTO `question_answer_info` VALUES ('1','How do I know if my class is cancelled?','Check the student portal or department notice.'),('10','What if two lectures overlap?','Inform your department immediately.'),('100','I\'m not sure whom to contact.','Visit the administration office or ask this chatbot for guidance.'),('101','How do I update my address?','Update it through the student portal.'),('102','Where can I find college policies?','Check the student handbook.'),('103','How do I request a document correction?','Submit a correction request to administration.'),('104','Can I get SMS updates?','If the notification service is enabled.'),('105','What time does college start?','9:30AM'),('106','What is the first lecture in1st semester in computer department?','M1'),('107','How many months does semester contains?','4 to 5 months'),('108','What type of competitions arrange in college?','Quiz competitions,didcipline and teamwork etc..'),('109','Does college arrange extra curriculum activities?','Yes they do arrange.'),('11','How do I register for exams?','Complete the online exam form before the deadline.'),('110','How many unit test conduct in one semester?','2 unit test.'),('111','does subject teachers take surprice test?','Yes they do take.'),('112','What is todays\'s timetable?','Todays\'s  timetable is available on the student portal.'),('113','What is the next class?','Please check today\'s timetable.'),('114','Who teaches java?','Tha java faculty teaches this subject.'),('115','Where is the computer lab?','on First floor,near to the reading room'),('116','Is attendance is compulsory?','Yes, attendance is compulsory.'),('117','What is my attendance?','Check your attendance on the portal.'),('118','What is the minimum attendance?','minimum attendance is 75%.'),('119','Can I see you my attendance?','Yes, on ths student portal.'),('12','I missed the exam form deadline.','Contact the examination cell immediately.'),('120','What happens if attendance is low?','Yo